window.RP_SESSION={"id":"S-5fe0125737ab","messages":[{"id":"RP-0247864","time":"2026-08-24T04:34:00+09:00","room":"RP","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"에스텔, 토르번, 올리브, 위크.","characters":["P-f310b84f8f20"]},{"id":"RP-0247865","time":"2026-08-24T04:34:00+09:00","room":"RP","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"네 명의 어설픈 용맹 사절단이 스카일라로 떠난다는 소식을 들었을 때 님드 앗질랄 아스사피 빈 칼리드 알 쿠라이시는 지원하지 않았다.","characters":["P-f310b84f8f20"]},{"id":"RP-0247866","time":"2026-08-24T04:38:00+09:00","room":"RP","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"스카일라에 가면 분명 집에도 들를 수 있겠고, 간만에 동생 와르다의 얼굴도 보고 편지로는 못다 한 얘기를 나눌 수도 있겠지.","characters":["P-f310b84f8f20"]},{"id":"RP-0247867","time":"2026-08-24T04:39:00+09:00","room":"RP","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"하지만 지금 흰 천에 둘러싸인 사내에게 고향으로 돌아가는 것은 적절치 못한 타이밍이었다.","characters":["P-f310b84f8f20"]},{"id":"RP-0247868","time":"2026-08-24T04:40:00+09:00","room":"RP","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"많은 사람이 반기겠지만, 적지 않은 사람이 반기지 않을 것이다.","characters":["P-f310b84f8f20"]},{"id":"RP-0247869","time":"2026-08-24T04:42:00+09:00","room":"RP","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"무기를 자꾸 깨먹어서 화난 대장장이 압둘알리 정도는 약과고","characters":["P-f310b84f8f20"]},{"id":"RP-0247870","time":"2026-08-24T04:48:00+09:00","room":"RP","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"알 나흐얀과 알 쿠라이시 간의 분쟁에 님드가 갑지기 나타나서 좋을게 없다.","characters":["P-f310b84f8f20"]},{"id":"RP-0247871","time":"2026-08-24T04:49:00+09:00","room":"RP","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"수많우 사람들이 자신에 대해 아는 스카일라로 돌아가 봐야 은퇴 전까지 받았던 손가락질을 다시 받을 뿐.","characters":["P-f310b84f8f20"]},{"id":"RP-0247872","time":"2026-08-24T04:51:00+09:00","room":"RP","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"돌을 찾을 때 까지 의뢰 외에 스카일라로 돌아갈 생각은 없다.","characters":["P-f310b84f8f20"]},{"id":"RP-0247873","time":"2026-08-24T04:51:00+09:00","room":"RP","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"어설픈 용맹에서 대륙 곳곳으로 모험을 다니며, 신비한 일들을 많이 겪었지만.","characters":["P-f310b84f8f20"]},{"id":"RP-0247874","time":"2026-08-24T04:52:00+09:00","room":"RP","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"아직 ■■■ ■■준다는 신비의 붉은 돌은 찾지 못했다.","characters":["P-f310b84f8f20"]},{"id":"RP-0247875","time":"2026-08-24T04:52:00+09:00","room":"RP","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그러는 새에 이 사람들과 어째 정이 든 것 같기도 해서, 떠날 때가 되면 섭섭할지도 모르겠다.","characters":["P-f310b84f8f20"]},{"id":"RP-0247876","time":"2026-08-24T04:52:00+09:00","room":"RP","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"떠난다...","characters":["P-f310b84f8f20"]},{"id":"RP-0247877","time":"2026-08-24T04:52:00+09:00","room":"RP","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그것도 돌을 찾아야 떠나지","characters":["P-f310b84f8f20"]},{"id":"RP-0247878","time":"2026-08-24T04:53:00+09:00","room":"RP","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"돌이 실존하지 않는다면 기왕 나온 김에 이 사람들 틈에서 살다가 죽어 고향이 아닌 곳에 묻혀도 좋겠다는 생각이 스멀스멀 피어오를 때 즈음.","characters":["P-f310b84f8f20"]},{"id":"RP-0247879","time":"2026-08-24T04:54:00+09:00","room":"RP","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"태양이 떠오른다.","characters":["P-f310b84f8f20"]},{"id":"RP-0247880","time":"2026-08-24T04:54:00+09:00","room":"RP","name":"님드","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-f310b84f8f20"]},{"id":"RP-0247881","time":"2026-08-24T04:54:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
